function e(e){let t=`transparent 0, black ${e}`,n=`black calc(100% - ${e}), transparent 100%`,r=`linear-gradient(to right, ${t}, black 100%)`,i=`linear-gradient(to right, black 0, ${n})`,a=`linear-gradient(to right, ${t}, ${n})`;return{scrollbarWidth:`none`,overscrollBehaviorX:`contain`,scrollPaddingInline:e,"&::-webkit-scrollbar":{display:`none`},"&[data-can-scroll-start][data-can-scroll-end]":{maskImage:a,WebkitMaskImage:a},"&[data-can-scroll-start]:not([data-can-scroll-end])":{maskImage:r,WebkitMaskImage:r},"&:not([data-can-scroll-start])[data-can-scroll-end]":{maskImage:i,WebkitMaskImage:i}}}export{e as t};